import {buildContextAssessment} from '../../../lib/credit-engine/context/engine.ts';
import {id,stable,rank} from '../../../lib/credit-engine/context/common.ts';
export const fingerprint=e=>id('context-golden',e);
export function checkContextCase(e,build=buildContextAssessment){const before=stable(e.input.riskAssessment),actual=build(e.input),mismatches=[];const check=(ok,code,expected,received,level='HARD')=>{if(!ok)mismatches.push({id:id('context-mismatch',e.caseId,code,expected,received),code,level,expected,actual:received});};
 for(const x of e.expected.requiredRelations??[]){const rs=actual.relations.filter(r=>r.code===x.code);check(rs.length>0,'MISSING_CONTEXT_RELATION',x.code,rs);for(const r of rs){if(x.effect)check(r.effect===x.effect,'CONTEXT_EFFECT_MISMATCH',x.effect,r.effect,x.level);if(x.targetRiskCode)check(r.targetRiskCodes.includes(x.targetRiskCode),'CONTEXT_TARGET_MISMATCH',x.targetRiskCode,r.targetRiskCodes,x.level);if(x.confidence)check(r.evidenceConfidence===x.confidence,'CONTEXT_CONFIDENCE_MISMATCH',x.confidence,r.evidenceConfidence,x.level);if(x.reasonCodes)check(x.reasonCodes.every(c=>r.reasonCodes.includes(c)),'CONTEXT_REASON_MISMATCH',x.reasonCodes,r.reasonCodes,x.level);}}
 for(const code of e.expected.forbiddenRelations??[])check(!actual.relations.some(r=>r.code===code),'FORBIDDEN_CONTEXT_RELATION',code,actual.relations.filter(r=>r.code===code));
 for(const x of e.expected.facts??[]){const fs=actual.facts.filter(f=>f.semanticCode===x.code);check(fs.length===1,'CONTEXT_FACT_PRESENCE',x.code,fs.length);if(fs.length===1)for(const k of ['value','status','confidence','sourceClass'])if(Object.hasOwn(x,k))check(stable(fs[0][k])===stable(x[k]),'CONTEXT_FACT_MISMATCH',{[k]:x[k]},fs[0][k],x.level);}
 for(const x of e.expected.ruleStatuses??[])check(actual.evaluations.some(r=>r.ruleCode===x.code&&r.status===x.status),'CONTEXT_RULE_STATUS_MISMATCH',x,actual.evaluations.filter(r=>r.ruleCode===x.code));
 for(const [k,v]of Object.entries(e.expected.summary??{}))check(actual.summary[k]===v,'CONTEXT_SUMMARY_MISMATCH',{[k]:v},actual.summary[k]);
 for(const code of e.expected.retainedRiskCodes??[])check(e.input.riskAssessment.findings.some(f=>f.code===code),'RISK_FINDING_NOT_RETAINED',code,e.input.riskAssessment.findings.map(f=>f.code));
 if(e.expected.invariants){check(stable(e.input.riskAssessment)===before,'RISK_ASSESSMENT_IMMUTABLE',true,false);check(!['score','pd','approvalProbability','products','debtCapacity','readiness','limits'].some(k=>k in actual),'CONTEXT_FORBIDDEN_OUTPUT',false,true);check(actual.facts.every(f=>f.status!=='UNKNOWN'||f.value===null),'UNKNOWN_NOT_ZERO',true,false);check(actual.relations.every(r=>r.contextFactIds.every(fid=>rank(r.evidenceConfidence)<=rank(actual.facts.find(f=>f.factId===fid).confidence))),'LOW_CONFIDENCE_NOT_PROMOTED',true,false);check(actual.relations.filter(r=>r.effect==='MITIGATES').every(r=>r.contextFactIds.some(fid=>actual.facts.find(f=>f.factId===fid).sourceClass!=='CLIENT_DECLARED')),'CLIENT_DECLARATION_NOT_HARD_PROOF',true,false);}
 if(e.expected.defectRegression){const f=e.input.riskAssessment.findings.find(f=>f.code==='RISK-BKI-CURRENT-OVERDUE');check(f?.severity==='MEDIUM'&&f.reasonCodes.includes('CURRENT_OVERDUE')&&!f.reasonCodes.some(r=>r.startsWith('DELINQUENCY_')),'CL_RU_DEFECT_001',true,f);check(!e.input.riskAssessment.findings.some(f=>f.code==='RISK-BKI-HISTORICAL-DELINQUENCY'),'HISTORY_ZERO_NOT_DELINQUENCY',true,false);}
 return {caseId:e.caseId,result:mismatches.some(m=>m.level==='HARD')?'FAIL':mismatches.length?'REVIEW':'PASS',mismatches,actual};}
export function runContextPack(pack){for(const e of pack.entries)if(pack.fingerprints[e.caseId]!==fingerprint(e))throw Error('CONTEXT_GOLDEN_FINGERPRINT_MISMATCH');return pack.entries.map(e=>checkContextCase(e));}
